import { ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, EventEmitter, Input, Output, QueryList, SimpleChanges, ViewChild, ViewChildren } from '@angular/core';

import Tribute from 'tributejs';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { ContactService } from '../../../../shared/services/contact/contact.service';
import { CommonModule } from '@angular/common';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { FormsModule } from '@angular/forms';
import { toolEvents } from '../../../interfaces/pdf.interface';
import { environment } from '../../../../../environments/environment';
import { NgScrollbar, NgScrollbarModule } from 'ngx-scrollbar';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
@Component({
  selector: 'fact-note',
  standalone: true,
  imports: [CommonModule, MatCheckboxModule, FormsModule, NgScrollbarModule, TranslateModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './fact-note.component.html',
  styleUrl: './fact-note.component.scss'
})
export class FactNoteComponent {

  imgPath: string = `${environment.documentStorage}${environment.userProfilePath}`;
  @ViewChildren('editableDiv') editableDivs: QueryList<ElementRef>;


  jEditedTexts: string[] = [''];

  @Input() type: 'F' | 'QF' = 'F';
  @Input() linkType: any = 'F';
  @Input() isAddNote: boolean = false;
  @Input() isnotHeader: boolean = true;

  @Input() nCaseid: string;

  @Input() jOTexts: string[] = [];
  @Input() jTexts: string[] = [];
  @Input() bIsHighlighted: boolean = false;
  @Output() jTextsChange = new EventEmitter<string[]>();
  @Output() bIsHighlightedChange = new EventEmitter<boolean>();
  @Output() updatejtext = new EventEmitter<any>();
  @Input() isEmpty: boolean;
  @Output() isEmptyChange = new EventEmitter<boolean>();
  isFocus: boolean = false;
  tribute: any;
  @Input() isNoteEdited: boolean = false;
  @Output() isNoteEditedChange = new EventEmitter<boolean>();
  @Output() onEvent = new EventEmitter<toolEvents>();
  constructor(private contactService: ContactService, private cdr: ChangeDetectorRef, private cf: CommonfunctionService, private translate: TranslateService) {

  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['jEditedTexts'] && !changes['jEditedTexts'].firstChange) {
      this.cdr.detectChanges();
    }

    if (changes['jTexts'] && !changes['jTexts'].firstChange) {
      this.ngOnInit();
    }
  }

  ngAfterViewInit(): void {
    this.focusLastDiv();
    this.setupPlaceholders();
  // NgScrollbar is only rendered when isnotHeader is true. In table mode
  // we use a native overflow container, so sb can be undefined.
  queueMicrotask(() => {
    if (this.sb && typeof this.sb.update === 'function') {
      this.sb.update();
    }
  });
  }




  @ViewChild(NgScrollbar) sb!: NgScrollbar;

  async ngOnInit() {
    if (this.type == 'QF' && this.isAddNote) {
      // this.jTexts.push('Note :&nbsp;');
      this.isNoteEdited = false;
      this.isNoteEditedChange.emit(this.isNoteEdited);
    }

    // Initialize editable buffer from incoming jTexts so existing
    // note content is visible when entering edit mode, without
    // mutating the bound jTexts value from the parent
    if (!this.jTexts || !this.jTexts.length) {
      this.jEditedTexts = [''];
    } else {
      this.jEditedTexts = [...this.jTexts];
    }

    const addContact = (item) => {
      this.onEvent.emit({ event: 'ADD-CONTECT', data: item })
    }


    const selectedContacts = await this.contactService.getContactList(this.nCaseid);

    this.tribute = new Tribute({
      values: selectedContacts,
      lookup: (contact) => {
        return `${contact?.cFname || ''} ${contact?.cLname || ''} ${contact?.cMentiontag || ''}`;
      },
      selectTemplate: function (item) {
        addContact(item)
        return `<a class='font-bold' id="${item.original.nContactid}">@${item.original.cFname} ${item.original.cLname}</a>`;
      },
      menuItemTemplate: (item) => {
        const avatar = this.genrateavatar(item.original);
        return `<div
            class="flex items-start gap-2  px-5 py-2.5 rounded-base mb-2 cursor-pointer">
            ${avatar}
            <div class="gap-1 flex flex-col">
              <span class="text-xs font-semibold">${item?.original?.cFname || ''} ${item?.original?.cLname || ''}
              </span>
              <span class="underline text-xxs leading-none truncate">${item?.original?.cMentiontag || ''}</span>
            </div>
          </div>`;
      }
    });

    this.attachTribute();
  }


  genrateavatar(detail: any) {
    let initials: any = this.cf.get_userinit2(detail);
    const firstName = initials.Fn;
    const lastName = initials.Ln;
    const bgColor = initials.bg;
    const path = this.imgPath + 'contacts/' + detail?.cProfile
    if (detail?.cProfile) {
      return `
    <span  
    class="inline-flex overflow-hidden size- items-center justify-center  rounded-full font-semibold text-white leading-none  border border-[#DAE2EA] size-[35px] text-[9px]">
    <ng-container *ngIf="detail?.cProfile">
    <img class="object-cover w-full h-full" src="${path}" (error)="assets/colorlogo.svg" >
    </ng-container>
    </span>`
    } else {
      return `
      <span 
      class="inline-flex overflow-hidden size- items-center justify-center ${bgColor}  rounded-full font-semibold text-white leading-none  border border-[#DAE2EA] size-[35px] text-[9px]">
        <ng-container *ngIf="!detail?.cProfile">
                <span>${firstName} ${lastName}</span>
        </ng-container>
      </span>`
    }
  }



  focusLastDiv(): void {
    const lastDiv = this.editableDivs.last;
    if (lastDiv) {
      const element = lastDiv.nativeElement;
      element.focus();
      // Place the cursor at the end of the text
      const range = document.createRange();
      const selection = window.getSelection();
      // Move the range to the end of the content
      range.selectNodeContents(element);
      range.collapse(false);
      // Apply the range to the selection
      selection?.removeAllRanges();
      selection?.addRange(range);
    }
  }

  onContainerClick(event: MouseEvent) {
    const target = event.target as HTMLElement;
    if (!target.isContentEditable && !target.closest('[contenteditable="true"]')) {
      this.focusLastDiv();
    }
  }

  attachTribute() {
    if (this.editableDivs) {
      this.editableDivs.forEach((editableDiv) => {
        this.tribute.attach(editableDiv.nativeElement);
        this.updatePlaceholder(editableDiv.nativeElement);
      });
    }
  }


  updateJText(event: Event, index: number): void {
    const target = event.target as HTMLElement;

    this.checkForIsNoteEdited(event, index);

    if (!this.jTexts[index]) {
      this.jTexts[index] = '';
    }
    this.jTexts[index] = target.innerHTML;
    this.jTextsChange.emit(this.jTexts);
    this.updatejtext.emit(this.jTexts);

    // Update placeholder state
    this.updatePlaceholder(target);


    this.isEmpty = false;
    if (!target.innerText || target.innerText.trim() == '') {
      this.isEmpty = true;
    }

    this.isEmptyChange.emit(this.isEmpty);
    this.cdr.detectChanges();
  }

  OnBackSpaceKeyUp(e, index) {
    const plainText: string = (e.target as HTMLElement).textContent || '';
    if (plainText == '') {

      const isNotLast = !(this.jEditedTexts?.length == 1);

      if (isNotLast) { //index
        if (this.jTexts?.length > index) {
          this.jTexts.splice(index, 1);
          this.jTextsChange.emit(this.jTexts);
        }
        if (this.jEditedTexts?.length > index) {
          this.jEditedTexts.splice(index, 1);
        }
        this.cdr.detectChanges();

        this.focusLastDiv();
        this.cdr.detectChanges();
      }
    }
  }

  checkForIsNoteEdited(e, index) {
    try {
      if (this.type == 'QF') {
        // const plainText: string = (e.target as HTMLElement).textContent || '';
        if (index == (this.jEditedTexts.length - 1)) {
          this.isNoteEdited = true;
          this.isNoteEditedChange.emit(this.isNoteEdited);
        }
      }
    } catch (error) {

    }
  }


  pushhilight(ev) {
    this.bIsHighlightedChange.emit(this.bIsHighlighted); // Use the EventEmitter


    setTimeout(() => {
      this.focusLastDiv();
      this.setupPlaceholders(); // Refresh placeholders after state change
    }, 100);


    // let disabledtext = this.jOTexts;
    // disabledtext.unshift('</div><div class="noteditable">')
    // disabledtext.push('</div><div class="editable">')
    // disabledtext.push('<span editable="false"> </span> Note : <br><br>');
    // if (ev.checked) {
    if (this.jEditedTexts.length < 0 && this.jEditedTexts[0] == '') {
      this.jEditedTexts[0] = 'Note : <br><br>';
    }
    //   setTimeout(() => {
    //     this.focusLastDiv();
    //   }, 100);
    // }
    // else {
    //   this.jEditedTexts = [''];
    // }
  }


  getPlaceholderText(): string {
    if (this.type === 'QF') {
      return this.translate.instant('FACTS.NOTE.PLACEHOLDER.ADD_NOTE');
    } else if (this.type === 'F') {
      return this.translate.instant('FACTS.NOTE.PLACEHOLDER.ADD_FACT_NOTE');
    }
    return this.translate.instant('FACTS.NOTE.PLACEHOLDER.START_TYPING');
  }


  setupPlaceholders(): void {
    if (this.editableDivs) {
      this.editableDivs.forEach((editableDiv) => {
        this.updatePlaceholder(editableDiv.nativeElement);
      });
    }
  }
  updatePlaceholder(element: HTMLElement): void {
    const hasContent = element.textContent && element.textContent.trim() !== '';
    if (!hasContent) {
      element.setAttribute('data-placeholder', this.getPlaceholderText());
      element.classList.add('show-placeholder');
    } else {
      element.classList.remove('show-placeholder');
    }
  }

}